def pattern(n: int) -> str:
    if n <= 0:
        return ""

    lines = []
    max_len = 0

    def get_row_content(k):
        if k == 0:
            return ""
        ascending = "".join(str(i % 10) for i in range(1, k + 1))
        descending = "".join(str(i % 10) for i in range(k - 1, 0, -1))
        return ascending + descending

    for i in range(1, n + 1):
        content = get_row_content(i)
        lines.append(content)
        if len(content) > max_len:
            max_len = len(content)

    for i in range(n - 1, 0, -1):
        content = get_row_content(i)
        lines.append(get_row_content(i))

    formatted_lines = [line.center(max_len) for line in lines]
    return "\n".join(formatted_lines)
